require_once __DIR__.'/../includes/bootstrap.php';
$title='Management Password Recovery';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$lookup=trim((string)($_POST['lookup']??''));
 $q=$pdo->prepare("SELECT user_id,username,email,phone FROM users WHERE LOWER(username)=LOWER(?) OR LOWER(COALESCE(email,''))=LOWER(?) OR REPLACE(REPLACE(COALESCE(phone,''),' ',''),'+','')=REPLACE(REPLACE(?,' ',''),'+','') LIMIT 1");$q->execute([$lookup,$lookup,$lookup]);$u=$q->fetch();
 if(!$u || empty($u['email'])) $err='No management account with a recovery email was found. The main administrator can add recovery details under Settings or Admin & Staff.';
 else { $token=bin2hex(random_bytes(32));$pdo->prepare('DELETE FROM admin_password_resets WHERE user_id=?')->execute([(int)$u['user_id']]);$pdo->prepare('INSERT INTO admin_password_resets(user_id,token_hash,expires_at) VALUES(?,?,?)')->execute([(int)$u['user_id'],hash('sha256',$token),date('Y-m-d H:i:s',time()+900)]);$url='https://shadrackinventory.infinityfree.me/auth/admin-reset-password.php?token='.urlencode($token);$sent=false;try{$sent=send_store_email((string)$u['email'],'Shadril management password recovery',store_email_template('MANAGEMENT SECURITY','Reset your management password','<p>Hello <strong>'.e($u['username']).'</strong>,</p><p>A password reset was requested for your management account. This secure link expires in 15 minutes and does not require an OTP.</p>','Reset management password',$url));}catch(Throwable $ignore){}if($sent)$msg='A secure password reset link has been sent to the registered recovery email.';else{$pdo->prepare('DELETE FROM admin_password_resets WHERE user_id=?')->execute([(int)$u['user_id']]);$err='The recovery email could not be sent. Check the management recovery email settings and try again.';}}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="icon" href="/assets/favicon.png"><link rel="stylesheet" href="/assets/style.css?v=21"><style><?=file_get_contents(__DIR__.'/../assets/style.css')?></style></head><body class="auth-body"><div class="auth-wrap"><div class="auth-page-back"><?=back_button('Previous page')?></div><div class="auth-card admin-auth"><img src="/assets/shadril-logo.png" style="width:78px;margin:auto;display:block" alt="Shadril Shopping Store"><span class="eyebrow">ADMIN & STAFF SECURITY</span><h1>Forgot management password?</h1><p>Works for the main administrator, Admin and Staff accounts. No OTP is used: a secure time-limited reset link is sent to the account's recovery email.</p><?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="errors"><?=e($err)?></div><?php endif;?><form method="post" class="form"><?=csrf_field()?><label>Username, email or phone<input name="lookup" required autocomplete="username"></label><button class="btn dark full">Send secure reset link</button></form><a class="btn home-return full" href="/auth/login.php">Back to management sign in</a><a class="management" href="/">Return to homepage</a></div></div></body></html>
